(() => {
'use strict';
const el=id=>document.getElementById(id),num=n=>Number.isFinite(n)?(Number.isInteger(n)?n.toLocaleString():String(n)):'Pending',dec=(n,p=6)=>Number.isFinite(n)?n.toFixed(p):'Pending';
const stages=[['features','SIFT extraction','CUDA'],['matching','Matching and verification','CUDA + CPU'],['mapping','Camera recovery / sparse model','CPU'],['bundle_adjustment','Bundle adjustment and filtering','CPU'],['undistortion','Calibrated image undistortion','CPU'],['depth_maps','Geometric depth / normals','CUDA'],['fusion','Dense fusion','CPU'],['mesh','Poisson meshing','CPU']];
Promise.all([fetch('insta360_results.json',{cache:'no-store'}).then(r=>r.json()),fetch('insta360-recovery-assets/gsplat.json',{cache:'no-store'}).then(r=>r.json()),fetch('insta360_recovery_common.json',{cache:'no-store'}).then(r=>r.json())]).then(([report,gs,common])=>{
 const scales=['1x','4x'],data=report.scales,primary=s=>Object.values(gs.models).find(m=>m.scale===s&&m.primary_component);
 el('insta-status').textContent=`Saved snapshot ${new Date(report.updated).toLocaleString()} · queue ${report.queue.state}. Results below are saved measurements, not a live stream.`;
 el('insta-quality-state').textContent=scales.map(s=>`${data[s].label}: ${num(data[s].geometry_quality?.cameras_with_median_observed_depth_below_1e_minus_5)} collapsed camera groups detected; original ${num(data[s].metrics.registered_images)}-view model retained for inspection.`).join(' ');
 const metrics=[['Image dimensions',d=>`${d.width} × ${d.height}`],['Input PNGs',d=>num(d.input_images)],['Storage, GB',d=>dec(d.storage_bytes/1e9,3)],['SIFT keypoints, all images',d=>num(d.sift_keypoints)],['Pairs with raw matches',d=>num(d.matching_counts?.matched_pairs)],['Geometrically verified pairs',d=>num(d.matching_counts?.verified_pairs)],['Verified feature correspondences',d=>num(d.matching_counts?.verified_inliers)],['Registered cameras, main component',d=>num(d.metrics.registered_images)],['Registered cameras, union of non-empty components',d=>num(d.registered_union)],['Sparse points, main component',d=>num(d.metrics.points3D)],['Sparse points, all components',d=>d.components.length?num(d.components.reduce((n,c)=>n+c.total_points,0)):'Pending'],['Non-empty / total components',d=>d.components.length?`${d.components.filter(c=>c.total_points).length} / ${d.components.length}`:'Pending'],['Mean reprojection error, input px',d=>dec(d.metrics.mean_reprojection_error)],['Full-resolution-equivalent error, px',d=>dec(d.metrics.full_resolution_equivalent_error_px)],['Mean track length',d=>dec(d.metrics.mean_track_length,3)],['Mapping linear-solver warnings',d=>num(d.solver_warning_count)],['Dense fused points',d=>num(d.dense?.vertex)],['Mesh vertices / faces',d=>`${num(d.mesh?.vertex)} / ${num(d.mesh?.face)}`]];
 el('insta-colmap-table').innerHTML=metrics.map(([label,get])=>`<tr><th scope="row">${label}</th>${scales.map(s=>`<td>${get(data[s])}</td>`).join('')}</tr>`).join('');
 el('insta-times').innerHTML=stages.map(([key,label,device])=>`<tr><th scope="row">${label}</th><td>${device}</td>${scales.map(s=>`<td>${data[s].stages[key]?.state==='complete'?dec(data[s].stages[key].seconds):data[s].stages[key]?.state||'Pending'}</td>`).join('')}</tr>`).join('');
 const cameraParams=s=>{const value=data[s].metrics.cameras?.[0]?.params;if(Array.isArray(value))return value;return typeof value==='string'?(value.match(/[-+]?(?:\d*\.)?\d+(?:[eE][-+]?\d+)?/g)||[]).map(Number):[]};
 el('insta-intrinsics').innerHTML=['fx','fy','cx','cy','k1','k2','k3','k4'].map((p,i)=>`<tr><th scope="row">${p}</th>${scales.map(s=>`<td>${dec(report.settings?.initial_camera_params[s][i])} → ${dec(cameraParams(s)[i])}</td>`).join('')}</tr>`).join('');
 const complete=Object.entries(gs.models).filter(([,m])=>m.state==='complete');
 el('insta-gs-table').innerHTML=Object.values(gs.models).length?Object.values(gs.models).map(m=>`<tr><th scope="row">${m.label} / ${m.component} · screened recovery</th><td>${m.registered_images} (${m.training_images} / ${m.validation_images})</td><td>${num(m.gaussian_count)} / ${num(m.trained_gaussian_count)}${m.excluded_invalid_gaussians?` · ${num(m.excluded_invalid_gaussians)} non-finite rows omitted`:''}</td><td>${m.state==='complete'?String(m.seconds):m.state}</td><td>${dec(m.metrics?.psnr)}</td><td>${dec(m.metrics?.ssim)}</td><td>${dec(m.metrics?.lpips)}</td><td>${m.state==='complete'?(m.validation_audit?.checkpoint_all_finite===false?'Checkpoint contains non-finite scales; exported PLY finite. ':'')+(m.visual_quality?.finding||'Appearance review pending.'):m.state}</td></tr>`).join(''):'<tr><td colspan="8">Training starts after the required calibrated cameras and images are ready.</td></tr>';
 el('insta-gs-quality').textContent='Both completed runs show partial, inconsistent appearance: the kitchen/table is recognizable, but several couch/window predictions are largely occluding color fields. All 854,975 native checkpoint and SH3 export rows are finite. The 4× checkpoint has 712 rows with negative-infinite log scales; its finite export omits those rows explicitly. Inspect the paired saved viewpoints.';
 el('insta-common-protocol').textContent=`${common.common_frame_count} shared held-out frames. ${common.protocol}`;
 el('insta-common-table').innerHTML=[['PSNR ↑','psnr'],['SSIM ↑','ssim'],['LPIPS ↓','lpips']].map(([label,key])=>`<tr><th scope="row">${label}</th>${scales.map(s=>`<td>${dec(common.models[s].mean[key])}</td>`).join('')}</tr>`).join('');
 el('insta-skipped').textContent=gs.skipped_components.length?`Small components retained only in COLMAP: ${gs.skipped_components.map(j=>`${j.label}, component${j.component}: ${j.registered_images} cameras / ${j.sparse_points} points`).join('; ')}. gsplat requires at least10 cameras and100 points for this experiment.`:'';
 const a=el('insta-render-a'),b=el('insta-render-b'),view=el('insta-viewpoint');
 for(const select of [a,b])select.replaceChildren(...Object.entries(gs.models).map(([key,m])=>new Option(`${m.label} / component${m.component}${m.state==='complete'?'':' · '+m.state}`,key)));
 a.value=Object.entries(gs.models).find(([,m])=>m.scale==='1x'&&m.primary_component)?.[0]||complete[0]?.[0]||'';b.value=Object.entries(gs.models).find(([,m])=>m.scale==='4x'&&m.primary_component)?.[0]||complete[0]?.[0]||'';
 function images(){for(const [select,target] of [[a,el('insta-image-a')],[b,el('insta-image-b')]]){const v=gs.models[select.value]?.views.find(v=>v.frame===view.value);target.replaceChildren();if(!v){target.textContent=`${gs.models[select.value]?.label||'Selected model'}: ${gs.models[select.value]?.state||'pending'}. No completed prediction for this viewpoint.`;continue;}const image=document.createElement('img');image.src=v.render;image.alt=`${gs.models[select.value].label}, ${v.frame}, Gaussian prediction`;image.style.width='100%';image.style.height='auto';const cap=document.createElement('p');cap.textContent=`${v.frame} · native prediction ${v.native_width} × ${v.native_height} · browser preview ${v.width} × ${v.height}`;target.append(image,cap);}}
 function choices(){const old=view.value,left=gs.models[a.value]?.views||[],rightViews=gs.models[b.value]?.views||[],right=new Set(rightViews.map(v=>v.frame));const shared=left.length&&rightViews.length?left.filter(v=>right.has(v.frame)):left.length?left:rightViews;view.replaceChildren(...shared.map(v=>new Option(v.frame,v.frame)));if(shared.some(v=>v.frame===old))view.value=old;images();}
 a.onchange=choices;b.onchange=choices;view.onchange=images;choices();
 const chartMetrics=[['SIFT keypoints',s=>data[s].sift_keypoints],['Sparse points, main component',s=>data[s].metrics.points3D],['Dense fused points',s=>data[s].dense?.vertex],['Full-resolution-equivalent error, px',s=>data[s].metrics.full_resolution_equivalent_error_px],['Valid exported Gaussians, main model',s=>primary(s)?.gaussian_count],['gsplat PSNR, native validation',s=>primary(s)?.metrics?.psnr],['gsplat SSIM, native validation',s=>primary(s)?.metrics?.ssim],['gsplat LPIPS, native validation',s=>primary(s)?.metrics?.lpips],['gsplat total process seconds',s=>primary(s)?.seconds],['gsplat PSNR, same 39 views',s=>common.models[s]?.mean.psnr],['gsplat SSIM, same 39 views',s=>common.models[s]?.mean.ssim],['gsplat LPIPS, same 39 views',s=>common.models[s]?.mean.lpips]];
 for(const [title,get] of chartMetrics){const figure=document.createElement('figure');figure.className='count-chart-panel';const cap=document.createElement('figcaption');const strong=document.createElement('strong');strong.textContent=title;cap.append(strong);figure.append(cap);const values=scales.map(s=>({x:Number.parseInt(s,10),y:get(s)}));if(values.some(v=>!Number.isFinite(v.y))){const p=document.createElement('p');p.textContent='Waiting for completed measurements at both resolutions.';figure.append(p);}else{const max=Math.max(...values.map(v=>v.y),.000001)*1.15;const x=v=>75+(v-1)/3*450,y=v=>265-v/max*210;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 640 340');svg.classList.add('count-line-chart');svg.setAttribute('role','img');svg.setAttribute('aria-label',`${title}: full resolution ${values[0].y},4x downsample ${values[1].y}`);svg.innerHTML=`${[0,.5,1].map(t=>`<line x1="75" y1="${y(max*t)}" x2="540" y2="${y(max*t)}" stroke="#ddd"/><text x="65" y="${y(max*t)+5}" text-anchor="end">${(max*t).toLocaleString(undefined,{maximumSignificantDigits:3})}</text>`).join('')}<line x1="75" y1="265" x2="540" y2="265" stroke="#222"/><polyline points="${values.map(v=>`${x(v.x)},${y(v.y)}`).join(' ')}" fill="none" stroke="#222" stroke-width="2"/>${values.map(v=>`<circle cx="${x(v.x)}" cy="${y(v.y)}" r="5" fill="#222"/><text x="${x(v.x)}" y="290" text-anchor="middle">${v.x}×</text>`).join('')}<text x="300" y="325" text-anchor="middle">Downsample factor</text>`;figure.append(svg);const p=document.createElement('p');p.className='chart-values';p.textContent=values.map(v=>`${v.x}×: ${num(v.y)}`).join(' · ');figure.append(p);}el('insta-charts').append(figure);}
}).catch(error=>{el('insta-status').textContent=`Saved results unavailable: ${error.message}`;});
})();
